# ETF 포트폴리오 리밸런서 — Windows 설치 스크립트
# PowerShell을 관리자로 실행하지 않아도 됩니다.
# 사용법: 이 파일을 바탕화면에 저장 후 PowerShell에서 실행:
#   Set-ExecutionPolicy Bypass -Scope Process; .\setup-windows.ps1

$ErrorActionPreference = "Stop"
$utf8NoBom = New-Object System.Text.UTF8Encoding $false

# 설치 폴더 선택 (바탕화면\portfolio-rebalancer)
$dir = Join-Path $env:USERPROFILE "Desktop\portfolio-rebalancer"
$pub = Join-Path $dir "public"

Write-Host "`n[1/4] 폴더 생성 중..." -ForegroundColor Cyan
New-Item -ItemType Directory -Force -Path $pub | Out-Null

Write-Host "[2/4] 파일 추출 중..." -ForegroundColor Cyan

function Write-B64File($path, $b64) {
    $bytes = [Convert]::FromBase64String($b64)
    [System.IO.File]::WriteAllBytes($path, $bytes)
}

Write-B64File (Join-Path $dir "package.json") ""
Write-B64File (Join-Path $dir "server.js") ""
Write-B64File (Join-Path $pub "index.html") ""
Write-B64File (Join-Path $pub "app.js") ""
Write-B64File (Join-Path $pub "style.css") ""
Write-B64File (Join-Path $pub "login.html") ""

Write-Host "[3/4] npm 패키지 설치 중... (처음 한 번만, 약 1분 소요)" -ForegroundColor Cyan
Set-Location $dir

# Check Node.js
try {
    $nodeVer = node --version 2>&1
    Write-Host "    Node.js $nodeVer 확인됨" -ForegroundColor Green
} catch {
    Write-Host "`n[오류] Node.js가 설치되지 않았습니다!" -ForegroundColor Red
    Write-Host "  https://nodejs.org 에서 LTS 버전을 설치한 후 다시 실행하세요." -ForegroundColor Yellow
    Read-Host "엔터를 눌러 종료"
    exit 1
}

npm install

Write-Host "[4/4] 서버 시작 중..." -ForegroundColor Cyan
Write-Host ""
Write-Host "  비밀번호: rebalance1234" -ForegroundColor Yellow
Write-Host "  접속 주소: http://localhost:3000" -ForegroundColor Green
Write-Host ""
Write-Host "  변경하려면: `$env:PORTFOLIO_PASSWORD='원하는비밀번호'; node server.js" -ForegroundColor Gray
Write-Host "  종료하려면: Ctrl+C" -ForegroundColor Gray
Write-Host ""

# Open browser after 2 seconds
Start-Job { Start-Sleep 2; Start-Process "http://localhost:3000" } | Out-Null

node server.js
